 &lt;td width=&quot;13%&quot; align=&quot;center&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lashunta-(Race).html&quot; title=&quot;Les lashuntas&quot;&gt;Les lashuntas&lt;/a&gt;&lt;/td&gt;
 &lt;td width=&quot;13%&quot; align=&quot;center&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Syrinx-(Race).html&quot; title=&quot;Les syrinx&quot;&gt;Les syrinx&lt;/a&gt;&lt;/td&gt;
 &lt;td width=&quot;13%&quot; align=&quot;center&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trox-(Race).html&quot; title=&quot;Les trox&quot;&gt;Les trox&lt;/a&gt;&lt;/td&gt;
 &lt;td width=&quot;13%&quot; align=&quot;center&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Triaxien-(Race).html&quot; title=&quot;Les triaxiens&quot;&gt;Les triaxiens&lt;/a&gt;&lt;/td&gt;
 &lt;td width=&quot;13%&quot; align=&quot;center&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Virebois-(Race).html&quot; title=&quot;Les virebois&quot;&gt;Les virebois&lt;/a&gt;&lt;/td&gt;
 &lt;td width=&quot;13%&quot; align=&quot;center&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Wivaran-(Race).html&quot; title=&quot;Les wivarans&quot;&gt;Les wivarans&lt;/a&gt;&lt;/td&gt;
